'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var Float64Array = require( '@stdlib/array/float64' );
var oneTo = require( '@stdlib/array/one-to' );
var zeros = require( '@stdlib/array/zeros' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var strides2offset = require( '@stdlib/ndarray/base/strides2offset' );
var descriptor = require( '@stdlib/ndarray/base/descriptor' );
var numel = require( '@stdlib/ndarray/base/numel' );
var dfill = require( '@stdlib/blas/ext/base/dfill' );
var ones = require( '@stdlib/array/ones' );
var add5 = require( '@stdlib/number/float64/base/add5' );
var kernel = require( './../lib' );
var LARGE_2D = require( './fixtures/large_2d.json' );
var LARGE_3D = require( './fixtures/large_3d.json' );
var LARGE_4D = require( './fixtures/large_4d.json' );
var LARGE_5D = require( './fixtures/large_5d.json' );
var LARGE_6D = require( './fixtures/large_6d.json' );
var LARGE_7D = require( './fixtures/large_7d.json' );
var LARGE_8D = require( './fixtures/large_8d.json' );
var LARGE_9D = require( './fixtures/large_9d.json' );
var LARGE_10D = require( './fixtures/large_10d.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof kernel, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns null if provided an unsupported number of dimensions', function test( t ) {
	t.strictEqual( kernel( -1 ), null, 'returns expected value' );
	t.strictEqual( kernel( 0 ), null, 'returns expected value' );
	t.strictEqual( kernel( 1 ), null, 'returns expected value' );
	t.strictEqual( kernel( 11 ), null, 'returns expected value' );
	t.strictEqual( kernel( 100 ), null, 'returns expected value' );
	t.end();
});

tape( 'the function returns a kernel for applying a quinary callback (row-major)', function test( t ) {
	var expected;
	var shapes;
	var sh;
	var st;
	var x;
	var v;
	var f;
	var i;

	shapes = [
		[ 2, 3 ],
		[ 2, 1, 3 ],
		[ 1, 2, 1, 3 ],
		[ 1, 1, 2, 1, 3 ],
		[ 1, 1, 1, 2, 1, 3 ],
		[ 1, 1, 1, 1, 2, 1, 3 ],
		[ 1, 1, 1, 1, 1, 2, 1, 3 ],
		[ 1, 1, 1, 1, 1, 1, 2, 1, 3 ],
		[ 1, 1, 1, 1, 1, 1, 1, 2, 1, 3 ]
	];
	expected = new Float64Array( [ 5.0, 10.0, 15.0, 20.0, 25.0, 30.0 ] );

	for ( i = 0; i < shapes.length; i++ ) {
		sh = shapes[ i ];
		st = shape2strides( sh, 'row-major' );

		x = descriptor( 'float64', oneTo( numel( sh ), 'float64' ), sh, st, strides2offset( sh, st ), 'row-major' );
		v = descriptor( 'float64', zeros( numel( sh ), 'float64' ), sh, st, strides2offset( sh, st ), 'row-major' );

		f = kernel( sh.length );
		f( x, x, x, x, x, v, add5 );
		t.strictEqual( isSameFloat64Array( v.data, expected ), true, 'returns expected value' );
	}
	t.end();
});

