tape( 'the function returns a kernel for applying a quinary callback (row-major, non-contiguous, large arrays)', function test( t ) {
	var fixtures;
	var expected;
	var strides;
	var shapes;
	var len;
	var sh;
	var st;
	var o;
	var x;
	var v;
	var f;
	var j;
	var i;

	fixtures = [
		LARGE_2D,
		LARGE_3D,
		LARGE_4D,
		LARGE_5D,
		LARGE_6D,
		LARGE_7D,
		LARGE_8D,
		LARGE_9D,
		LARGE_10D
	];
	for ( j = 0; j < fixtures.length; j++ ) {
		shapes = fixtures[ j ].row_major_shapes;
		strides = fixtures[ j ].row_major_strides;
		for ( i = 0; i < shapes.length; i++ ) {
			sh = shapes[ i ];
			st = strides[ i ];
			o = strides2offset( sh, st );
			len = numel( sh );

			x = descriptor( 'float64', ones( len*2, 'float64' ), sh, st, o, 'row-major' );
			v = descriptor( 'float64', zeros( len*2, 'float64' ), sh, st, o, 'row-major' );

			f = kernel( sh.length );
			f( x, x, x, x, x, v, add5 );

			expected = new Float64Array( len*2 );
			dfill( len, 5.0, expected, st[ sh.length-1 ] );
			t.strictEqual( isSameFloat64Array( v.data, expected ), true, 'returns expected value' );
		}
	}
	t.end();
});

tape( 'the function returns a kernel for applying a quinary callback (column-major, non-contiguous, large arrays)', function test( t ) {
	var fixtures;
	var expected;
	var strides;
	var shapes;
	var len;
	var sh;
	var st;
	var o;
	var x;
	var v;
	var f;
	var j;
	var i;

	fixtures = [
		LARGE_2D,
		LARGE_3D,
		LARGE_4D,
		LARGE_5D,
		LARGE_6D,
		LARGE_7D,
		LARGE_8D,
		LARGE_9D,
		LARGE_10D
	];
	for ( j = 0; j < fixtures.length; j++ ) {
		shapes = fixtures[ j ].column_major_shapes;
		strides = fixtures[ j ].column_major_strides;
		for ( i = 0; i < shapes.length; i++ ) {
			sh = shapes[ i ];
			st = strides[ i ];
			o = strides2offset( sh, st );
			len = numel( sh );

			x = descriptor( 'float64', ones( len*2, 'float64' ), sh, st, o, 'column-major' );
			v = descriptor( 'float64', zeros( len*2, 'float64' ), sh, st, o, 'column-major' );

			f = kernel( sh.length );
			f( x, x, x, x, x, v, add5 );

			expected = new Float64Array( len*2 );
			dfill( len, 5.0, expected, st[ 0 ] );
			t.strictEqual( isSameFloat64Array( v.data, expected ), true, 'returns expected value' );
		}
	}
	t.end();
});
